export const DATA_19: ReadingTest[] = [
  { id: "rd-024", num: 24, title: "Đề 024", timeMin: 60, parts: [
    { title: "The Evolution of Modern Food Habits", paragraphs: ["A century ago, most families in industrialized countries prepared nearly every meal from raw ingredients bought at a local market or grown in a home garden. Refrigeration, mass transportation, and improved food preservation techniques gradually changed this pattern by making a much wider variety of foods available throughout the year rather than only during a short harvest season. Canned goods and, later, frozen dinners let households store food for weeks or months without spoiling, a convenience that earlier generations simply did not have. These changes quietly reshaped not just what people ate, but how much time eating actually required.", "Supermarkets began replacing small specialty shops in many cities during the mid-twentieth century, offering shoppers a single location where they could buy meat, vegetables, and packaged goods together. Food companies increasingly relied on advertising to promote branded products, often emphasizing speed and convenience over the traditional value of a home-cooked meal. Fast-food restaurants expanded rapidly during this same period, serving standardized meals that tasted the same whether a customer visited a location in one city or another. For many families, a quick meal eaten outside the home gradually stopped feeling like an occasional treat and instead became a routine part of daily life.", "As more women entered paid employment from the 1960s onward, the amount of time available for daily meal preparation in many households noticeably declined. Ready-made meals and takeout food offered a practical solution for busy parents juggling work schedules and childcare responsibilities. Restaurants and food-delivery services adjusted their offerings accordingly, introducing express lunch menus and, eventually, apps that let customers order food without visiting a restaurant at all. Eating together as a family, once a near-universal daily habit, slowly became less common in households where every family member kept a different schedule.", "By the late twentieth century, public health officials had begun warning that rising rates of obesity and diet-related illness were closely linked to the widespread consumption of processed, high-calorie convenience foods. Nutrition labels became mandatory in many countries, giving consumers clearer information about the sugar, fat, and salt content of packaged products they had previously purchased without much thought. Some shoppers responded by seeking out organic produce, home-cooked meals, and diets built around whole, unprocessed ingredients rather than pre-packaged alternatives. Public schools in several countries also revised cafeteria menus, removing some of the least nutritious options that had long been standard.", "Today, food habits continue to shift alongside new technology and changing personal values. Meal-kit subscription services now deliver pre-measured ingredients and simple recipes directly to customers' doors, promising the convenience of takeout with something closer to the experience of cooking at home. Plant-based diets have also grown noticeably more popular, driven partly by health concerns and partly by environmental awareness about the resources required to produce meat. Whatever direction these trends take next, the basic story of the last century remains one of convenience steadily reshaping how, when, and what people eat."], questions: [{ q: "According to the passage, what did canned goods and frozen dinners allow households to do?", options: ["Refrigeration and transportation made more foods available yearly.", "Households could only store fresh food for a few days.", "Earlier generations had this same storage convenience too.", "Households could keep food safe for a long time."], answer: 3 }, { q: "The word \"branded\" in paragraph 2 is closest in meaning to _______.", options: ["labeled", "expensive", "banned", "seasonal"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Supermarkets replaced small specialty shops in many cities.", "Fast food has now completely replaced home cooking everywhere.", "Convenience steadily reshaped how and what people eat.", "Health concerns mainly drove all changes in eating habits."], answer: 2 }, { q: "The phrase \"These changes\" in paragraph 1 refers to _______.", options: ["new refrigeration and preservation methods", "canned goods", "a short harvest season", "frozen dinners"], answer: 0 }, { q: "According to the passage, what happened as more women entered paid employment?", options: ["Ready-made meals helped busy parents manage their schedules.", "More time became available for daily meal preparation.", "This shift in time began mostly in the 1980s.", "Less time was available at home for cooking meals."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a response to concerns about processed food?", options: ["Nutrition labels became required on packaged products.", "Governments banned the sale of all fast food restaurants.", "Some people chose organic produce and home cooking.", "Schools removed some of the least nutritious cafeteria items."], answer: 1 }, { q: "The word \"subscription\" in paragraph 5 is closest in meaning to _______.", options: ["membership", "one-time purchase", "delivery", "advertisement"], answer: 0 }, { q: "According to the passage, why have plant-based diets grown more popular?", options: ["Meal kits deliver pre-measured ingredients to customers' doors.", "Only environmental awareness explains their growing popularity.", "Government regulations mainly caused their growing popularity.", "Health and environmental concerns both increased their popularity."], answer: 3 }, { q: "What can be inferred about family meals over the twentieth century?", options: ["Shared family meals have generally become less frequent over time.", "Family meals have completely disappeared in modern households.", "Families eating apart caused parents to seek more employment.", "Supermarkets began replacing small specialty shops in many cities."], answer: 0 }, { q: "What is the author's attitude toward the changes in modern food habits?", options: ["The author strongly condemns all fast-food companies' practices.", "The author remains deeply alarmed about modern eating habits.", "The author enthusiastically endorses plant-based diets exclusively.", "The author describes the changes mainly as informative and balanced."], answer: 3 }] },
    { title: "Digital Transformation in Modern Education", paragraphs: ["Long before health restrictions forced classrooms worldwide to move online almost overnight, schools had already been gradually incorporating digital tools into daily instruction, a shift that the sudden crisis merely compressed into a matter of weeks rather than years. What had once been an optional supplement, limited mostly to a weekly visit to a computer lab, quickly became the primary medium through which many students accessed lessons, submitted assignments, and communicated with teachers. Few educators anticipated how permanently this abrupt transition would reshape expectations about what a normal classroom should include.", "Educational technology did not appear suddenly; it built on decades of incremental change beginning with early computer-assisted instruction programs in the 1980s, which offered little more than simple drills and multiple-choice quizzes on standalone machines. The spread of internet access through the 1990s and 2000s enabled richer resources, including recorded lectures, interactive simulations, and eventually cloud-based learning management systems capable of tracking assignments, grades, and communication in one centralized platform. By the time mobile devices became widespread, most students carried access to nearly the entire toolkit in their pockets.", "Proponents of digital learning tools point to adaptive software capable of adjusting question difficulty in real time based on a student's previous answers, theoretically allowing each learner to progress at an individually appropriate pace rather than a fixed classroom rhythm. Immediate feedback, unavailable in most traditional paper-based assignments graded days or weeks later, lets students identify and correct misunderstandings while the relevant material is still fresh. Digital platforms also grant access to a breadth of supplementary material, from primary historical documents to interactive science simulations, that a single physical textbook could never realistically contain.", "These advantages, however, depend heavily on reliable access to devices and stable internet connections, resources still unevenly distributed both within and between countries. Students from lower-income households frequently share a single device among several family members or rely entirely on public Wi-Fi, a disadvantage that widened noticeably during periods of remote instruction. Some pediatric health researchers have also raised concerns about the cumulative screen time that digital learning adds atop students' existing recreational device use, though comprehensive long-term data on the resulting effects remains limited.", "As digital platforms take over more routine tasks such as grading multiple-choice quizzes and tracking attendance, many teachers report spending relatively less classroom time lecturing and more time facilitating small-group discussion or one-on-one support. This shift demands a different, often unfamiliar skill set, and school systems have not uniformly provided the training needed to use new platforms effectively rather than merely digitizing old lecture-based habits. Some researchers suggest this facilitator-style approach may improve outcomes for certain subjects, though the existing evidence remains mixed and appears to depend considerably on how thoroughly teachers were actually trained beforehand.", "Debate continues over whether gamified elements such as points, badges, and leaderboards genuinely deepen learning or merely make an otherwise unchanged curriculum feel more entertaining in the short term. A number of classroom studies report short-term motivation gains among students exposed to gamified platforms, yet few of these studies track whether the resulting knowledge is retained months later, once the novelty of badges and points has worn off. Some critics argue that engagement metrics themselves may be a poor proxy for genuine long-term learning.", "Looking ahead, most education researchers expect neither a full return to pre-digital classrooms nor a complete replacement of teachers by software, but rather some hybrid arrangement that combines direct human instruction with targeted digital support, including emerging AI-based tutoring tools still being tested in limited pilot programs. Whether this blended future actually narrows or widens existing gaps in educational access will likely depend less on the technology itself than on how deliberately schools address the unequal starting points from which students begin."], questions: [{ q: "According to the passage, what did early computer-assisted instruction programs in the 1980s offer?", options: ["Mobile devices eventually let students carry the entire toolkit.", "Early programs offered advanced interactive simulations for students.", "This basic drill software first appeared in the 2000s.", "Early programs mainly offered basic drills on individual computers."], answer: 3 }, { q: "The word \"compressed\" in paragraph 1 is closest in meaning to _______.", options: ["condensed", "eliminated", "digitized", "compromised"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Adaptive software adjusts question difficulty for each student.", "Gamified platforms have proven to permanently improve all learning.", "Digital tools have reshaped education while raising unresolved questions.", "Most researchers now favor abandoning digital tools altogether."], answer: 2 }, { q: "The phrase \"This shift\" in paragraph 5 refers to _______.", options: ["teachers facilitating more than lecturing", "grading multiple-choice quizzes", "small-group discussion", "tracking attendance"], answer: 0 }, { q: "According to the passage, what disadvantage do lower-income students often face?", options: ["Screen time concerns remain understudied over the long term.", "This access gap narrowed considerably during remote instruction.", "Wealthier households mainly struggled with shared device access.", "Lower-income students often share devices or rely on public Wi-Fi."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a benefit of digital learning tools?", options: ["Adaptive software can adjust difficulty based on prior answers.", "Digital tools automatically translate lessons into any language.", "Immediate feedback lets every student instantly fix all misunderstandings.", "Digital platforms provide access to supplementary learning materials."], answer: 1 }, { q: "What can be inferred about the overall evidence on digital learning's effectiveness?", options: ["Research has firmly proven digital tools improve all learning outcomes.", "Poor teacher training caused schools to adopt digital platforms.", "Gamified platforms use points, badges, and leaderboards to motivate students.", "Current evidence on its effectiveness remains incomplete and mixed."], answer: 3 }, { q: "The word \"novelty\" in paragraph 6 is closest in meaning to _______.", options: ["excitement", "newness", "difficulty", "novel"], answer: 1 }, { q: "According to the passage, what do most education researchers expect for the future of classrooms?", options: ["AI tutoring tools are still being tested in limited pilots.", "Most researchers expect a full return to pre-digital classrooms.", "Most researchers expect software to fully replace teachers soon.", "Most researchers expect a hybrid mix of teaching methods."], answer: 3 }, { q: "What is the author's overall attitude toward the digital transformation of education?", options: ["The author treats the transformation as promising yet still uncertain.", "The author mainly warns that screen time harms children severely.", "The author is entirely confident digital tools will succeed.", "The author fully celebrates gamification as proven and effective."], answer: 0 }] },
    { title: "The Gig Economy: Rise of the Delivery Workforce", paragraphs: ["Within little more than a decade, app-mediated delivery work has expanded from a marginal urban curiosity into a labor category that regulators, courts, and researchers alike continue to struggle to classify cleanly. Platforms connecting couriers to restaurants and retailers now operate in most major cities worldwide, yet the legal status of the individuals fulfilling these deliveries remains contested precisely because the arrangement resists the binary distinction, employee or independent contractor, that most existing labor law was built around.", "While earlier forms of piecework, such as door-to-door sales or freelance courier services, share superficial similarities with today's platforms, what distinguishes app-based delivery is the degree to which an algorithm, rather than a human supervisor, allocates tasks, sets effective pay rates, and can suspend access to work entirely without the kind of formal disciplinary process traditionally required before dismissal. This algorithmic intermediation, largely invisible to customers who see only a delivery estimate, has become the central point of dispute in most legal challenges brought against these companies.", "Proponents of the model, including many workers themselves, emphasize the flexibility it affords: shifts can be logged in or abandoned at will, multiple platforms can be combined to smooth out gaps in demand, and no fixed schedule need be negotiated with a manager. Surveys conducted across several countries suggest that a meaningful share of couriers value this autonomy more than the security associated with conventional employment, particularly among those balancing delivery work with caregiving responsibilities or additional jobs elsewhere.", "Critics counter that this flexibility is frequently more theoretical than practical, since algorithmic incentive structures often penalize couriers who decline low-paying assignments or who fail to maintain a narrow acceptance-rate threshold, effectively coercing continuous availability despite the formal absence of a fixed schedule. Because most platforms classify couriers as independent contractors, workers in many jurisdictions bear the full cost of vehicle maintenance, fuel, and insurance themselves, and typically receive no guaranteed minimum pay, no employer-funded healthcare, and no compensation for the unpaid time spent waiting between assignments.", "Regulatory responses have diverged sharply across jurisdictions: some governments have moved to reclassify couriers as employees entitled to standard protections, while others have introduced an intermediate legal category carrying limited benefits without full employment status, and a third group has largely left the existing contractor framework untouched. Each approach carries distinct trade-offs that rarely satisfy every stakeholder simultaneously; reclassification tends to raise platforms' operating costs, which companies argue could reduce the number of available delivery slots, while leaving the framework unchanged preserves flexibility at the cost of leaving income volatility largely unaddressed.", "Consumers, for their part, have grown accustomed to delivery speeds and price points that many economists argue would be difficult to sustain if platforms fully internalized the labor costs that reclassification would impose, suggesting that any resolution favorable to couriers may carry consequences that ripple outward to pricing structures and delivery availability more broadly. Whether such trade-offs would prove temporary, as platforms adjust their models, or persistent, as some economists contend, remains an open empirical question rather than a settled matter.", "What seems clear amid this uncertainty is that the delivery workforce has already outgrown the legal categories built to contain it, and that any lasting settlement will likely require legislators to define an entirely new classification rather than stretching existing employment law to accommodate an arrangement it was never designed to describe."], questions: [{ q: "According to the passage, how does algorithmic management typically limit couriers' practical flexibility?", options: ["It removes each courier's need to negotiate a fixed schedule.", "It requires couriers to complete formal disciplinary hearings first.", "It discourages refusing assignments by penalizing low acceptance rates.", "It guarantees a minimum acceptance rate to boost courier pay."], answer: 2 }, { q: "The word \"internalized\" in paragraph 6 is closest in meaning to _______.", options: ["absorbed", "eliminated", "internationalized", "advertised"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Algorithmic systems determine couriers' pay and task assignments.", "Consumer pricing concerns outweigh worries about courier welfare in the debate.", "All governments have now reclassified couriers as full employees.", "Delivery work's flexibility and its costs remain unresolved regulatory tensions."], answer: 3 }, { q: "The word \"which\" in paragraph 5 refers to _______.", options: ["available delivery slots", "operating costs rising", "existing contractor framework", "income volatility"], answer: 1 }, { q: "According to the passage, what trade-off is associated with leaving the contractor framework unchanged?", options: ["Reclassification tends to raise platforms' overall operating costs.", "It guarantees couriers full employer-funded healthcare coverage.", "It keeps flexibility while leaving income instability unresolved.", "It immediately reduces companies' available delivery capacity."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a cost typically borne by couriers classified as contractors?", options: ["They must pay a mandatory platform registration fee upfront.", "They pay for their own vehicle maintenance and fuel.", "They receive no compensation for unpaid waiting time.", "They typically lack access to employer-funded healthcare."], answer: 0 }, { q: "What can be inferred about the likely resolution of the regulatory uncertainty surrounding delivery work?", options: ["Existing employment law will eventually be stretched to cover couriers fully.", "Consumer demand for fast delivery caused algorithmic management systems to emerge.", "Some jurisdictions have introduced an intermediate legal category already.", "A wholly new legal category will likely be required eventually."], answer: 3 }, { q: "The word \"coercing\" in paragraph 4 is closest in meaning to _______.", options: ["encouraging", "forcing", "scheduling", "coordinating"], answer: 1 }, { q: "According to the passage, what do economists suggest could happen if platforms fully absorbed courier labor costs?", options: ["Couriers currently bear vehicle costs like fuel and insurance.", "Delivery speeds would improve regardless of any cost changes.", "Current delivery prices and speeds might become harder to maintain.", "Consumer prices would permanently fall as competition increases."], answer: 2 }, { q: "What is the author's overall purpose in presenting both the flexibility argument and the precarity argument?", options: ["To present the debate as genuinely unresolved and complex.", "To argue that algorithmic management should be banned outright.", "To celebrate the flexibility that gig work provides workers.", "To strongly recommend immediate reclassification of all couriers."], answer: 0 }] },
    { title: "Quantum Computing and the Future of Cryptography", paragraphs: ["Not only have quantum computers remained largely theoretical curiosities for much of their history, but the handful of machines built so far have also proven too error-prone and too limited in qubit count to threaten any cryptographic system presently in commercial use. Nevertheless, the mere possibility that a sufficiently large, fault-tolerant quantum machine could eventually be built has already reshaped how governments and technology companies plan for long-term data security, since information encrypted today could, in principle, be harvested now and decrypted retroactively once such a machine exists.", "Much of this anxiety traces back to a single theoretical result from the 1990s demonstrating that a sufficiently powerful quantum computer could factor large numbers exponentially faster than any known classical method, a capability that would, if realized at scale, undermine the mathematical assumption underlying most widely deployed public-key encryption. [1] Symmetric encryption schemes, by contrast, appear comparatively resistant, since the best-known quantum attack against them merely halves their effective security strength rather than eliminating it entirely, a degradation that can typically be offset simply by doubling key length.", "Estimates of when a cryptographically relevant quantum computer might actually exist vary enormously among specialists, ranging from within the next decade to several decades away, or, according to a persistent minority view, possibly never, given unresolved physical obstacles to maintaining quantum coherence at the scale required. [2] This wide uncertainty has not, however, deterred a significant portion of the security industry from proceeding as though the threat were imminent, on the reasoning that migrating cryptographic infrastructure is itself a multi-year undertaking that cannot simply be initiated once a working machine is announced.", "In response, standards bodies have already begun formalizing so-called post-quantum cryptographic algorithms, mathematical schemes designed to resist both classical and quantum attack, though the transition these standards require is complicated considerably by the sheer number of existing systems, from banking infrastructure to embedded medical devices, that would need to be updated or replaced. [3] Some of the earliest proposed post-quantum algorithms have themselves since been broken by classical, non-quantum techniques, a pattern that has left several cryptographers arguing for caution rather than haste in how quickly any single new standard is trusted.", "Because cryptographic transitions of this scale are rarely coordinated smoothly across every affected institution simultaneously, some analysts argue that whichever nation or company first achieves a reliable cryptographically relevant quantum computer would gain not merely a scientific milestone but a temporary strategic advantage, capable of decrypting previously harvested communications before rivals have completed their own migration to quantum-resistant standards. [4] Other specialists counter that such an advantage, even if achieved, would likely prove short-lived and difficult to exploit covertly, since any conspicuous pattern of successfully broken encryption would itself signal the capability's existence to adversaries.", "Skeptics of the more urgent narratives surrounding quantum decryption caution that popular coverage frequently conflates near-term, limited quantum devices with the much larger, error-corrected machines that any real cryptographic threat would actually require, a distinction that is often lost amid commercially motivated announcements of quantum breakthroughs. Whether this skepticism reflects genuine technical grounds for delay or simply reflects the inherent difficulty of forecasting a technology still under active development remains a matter specialists have not settled.", "Whatever the precise timeline eventually proves to be, the asymmetry between the modest cost of migrating to quantum-resistant standards now and the potentially catastrophic cost of retroactive decryption later has convinced most institutions handling sensitive long-term data that preparation, however uncertain the underlying threat's timing, is unlikely to constitute wasted effort."], questions: [{ q: "What is the main idea of the passage?", options: ["Quantum decryption risk is imminent and virtually guaranteed within years.", "Quantum decryption risk is real but its timeline stays deeply uncertain.", "Quantum decryption risk is negligible and safely dismissed by most experts.", "Quantum decryption risk threatens all forms of encryption equally today."], answer: 1 }, { q: "According to the passage, how does the best-known quantum attack affect symmetric encryption?", options: ["It completely eliminates the security of symmetric encryption schemes.", "It affects public-key encryption more severely than symmetric encryption.", "Doubling key length caused the quantum attack to weaken.", "It reduces, but does not eliminate, its effective security strength."], answer: 3 }, { q: "The word \"harvested\" in paragraph 1 is closest in meaning to _______.", options: ["collected", "stolen", "encrypted", "harnessed"], answer: 0 }, { q: "The word \"it\" in paragraph 2 refers to _______.", options: ["the quantum attack", "symmetric encryption schemes", "effective security strength", "key length"], answer: 2 }, { q: "According to the passage, which of the following is NOT presented as a reason for caution in adopting new post-quantum standards?", options: ["Some early post-quantum algorithms have already been broken classically.", "All post-quantum algorithms have already proven completely unbreakable by any method.", "Migrating existing systems requires updating a very large number of them.", "Quantum computers themselves are prohibitively expensive to manufacture at scale."], answer: 3 }, { q: "What can be inferred about the strategic value of being first to build a cryptographically relevant quantum computer?", options: ["Such an advantage would certainly guarantee permanent global dominance.", "Any such advantage would likely be brief and hard to conceal.", "Encryption failures elsewhere would cause a nation to build one.", "Such an advantage would apply equally to every possible rival nation."], answer: 1 }, { q: "The word \"conflates\" in paragraph 6 is closest in meaning to _______.", options: ["blurs together", "separates", "publicizes", "conflicts"], answer: 0 }, { q: "According to the passage, what has the security industry done despite wide uncertainty about quantum timelines?", options: ["Nearly every institution has already fully completed its migration.", "Only government agencies have started preparing for this threat.", "Many have begun migrating as though the threat were near.", "Migration efforts caused the timeline uncertainty to increase."], answer: 2 }, { q: "How does the author primarily structure the discussion of quantum computing's cryptographic threat?", options: ["By focusing mainly on the mechanics of Shor's algorithm.", "By balancing urgent warnings against genuine scientific uncertainty and skepticism.", "By dismissing all quantum threat concerns as pure hype.", "By strongly endorsing immediate replacement of all encryption systems."], answer: 1 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This vulnerability explains why researchers have prioritized replacing key-exchange and digital-signature protocols well before addressing symmetric encryption.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }] },
  ] },
  { id: "rd-178", num: 178, title: "Đề 178", timeMin: 60, parts: [
    { title: "Chè: A Traditional Vietnamese Sweet Soup", paragraphs: ["Among the many desserts enjoyed across Vietnam, few are as varied or as widely loved as chè, a broad category of sweet soups and puddings served either warm or over crushed ice. Unlike many desserts found in Western countries, chè is rarely a single fixed recipe; instead, the name covers dozens of different combinations of beans, fruit, coconut milk, and sugar, each with its own texture and flavor. Some versions are thick and creamy, while others are light and watery, closer to a sweet drink than a solid dessert. This flexibility , along with its affordability , has helped chè remain a favorite treat for people of every age and background.", "The exact origins of chè are difficult to trace with certainty, since recipes were passed down orally from grandmother to mother to daughter long before they were ever written in cookbooks. Most food historians agree that chè developed gradually over centuries, shaped by whatever ingredients were locally available in each region. In the north, chè recipes often rely on mung beans and lotus seeds, reflecting the cooler climate and different farming traditions. Further south, tropical fruits such as jackfruit and durian appear more frequently, along with generous amounts of coconut milk, giving southern chè a noticeably richer and sweeter taste overall.", "Preparing chè usually begins with cooking the main ingredient, whether beans, taro, or tapioca pearls, until soft, then sweetening it with sugar and often flavoring it with pandan leaves for a mild, grassy aroma. Coconut milk is commonly poured over the finished dish just before serving, adding richness without overpowering the other flavors. Some varieties include unusual textures, such as chewy tapioca balls or soft, jelly-like pieces made from agar. Because chè can be served either hot during cooler months or cold over ice in the summer heat, the same basic dish can feel completely different depending on when and how it is prepared.", "Chè holds a special place at Vietnamese family gatherings, religious ceremonies, and important life events such as weddings and death anniversaries, where a particular type of chè is often prepared to honor ancestors or celebrate good fortune. Street vendors selling chè from small carts or simple stalls remain a common sight in cities, offering an inexpensive treat that students and workers can enjoy between meals. For many overseas Vietnamese communities, learning to make chè from an older relative has also become a way of staying connected to family traditions and cultural identity while living far from home.", "Today, chè continues to evolve, with modern cafes experimenting with new flavors such as matcha, chocolate, and even cheese foam poured over traditional bean mixtures. Despite these changes, most Vietnamese people still consider chè an essential comfort food, one that connects them to childhood memories and family recipes passed down through generations."], questions: [{ q: "According to the passage, what ingredients are commonly used in northern chè recipes?", options: ["Jackfruit and durian are the most common ingredients.", "Tapioca pearls replaced beans in most northern recipes.", "Coconut milk is used exclusively, without any beans.", "Mung beans and lotus seeds are commonly used."], answer: 3 }, { q: "What is the main idea of the passage?", options: ["Every Vietnamese chè recipe has now been written in cookbooks.", "Northern chè has completely replaced southern chè recipes today.", "Chè is a varied, affordable dessert with strong cultural roots.", "Chè is only made using mung beans and coconut milk."], answer: 2 }, { q: "The word \"affordability\" in paragraph 1 is closest in meaning to _______.", options: ["affability", "popularity", "cheapness", "worthlessness"], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as part of chè?", options: ["Chewy tapioca balls used for texture", "Coconut milk poured over finished chè", "Mung beans used in many chè recipes", "Rice noodles included in traditional chè"], answer: 3 }, { q: "According to the passage, what is pandan leaf typically used for when preparing chè?", options: ["It replaces sugar as the main sweetening ingredient.", "It is used to thicken the coconut milk topping.", "It adds a mild, grassy aroma to the dish.", "It adds a mild, grassy aroma to the dish only."], answer: 2 }, { q: "The phrase \"This flexibility\" in paragraph 1 refers to _______.", options: ["affordability", "the many different chè combinations", "watery texture", "sugar"], answer: 1 }, { q: "According to the passage, when is a particular type of chè often prepared?", options: ["During school exams to bring good luck.", "During death anniversaries to honor ancestors.", "During ordinary weekday breakfasts at home.", "Only when overseas relatives visit briefly."], answer: 1 }, { q: "The word \"overpowering\" in paragraph 3 is closest in meaning to _______.", options: ["touching", "sweetening", "overflowing", "dominating"], answer: 3 }, { q: "What can be inferred from the passage about how chè recipes have traditionally been passed down?", options: ["Cookbooks caused families to begin cooking chè.", "They were fully documented before ever being cooked.", "They were mainly shared orally within families.", "Southern chè tends to taste richer and sweeter."], answer: 2 }, { q: "What is the author's attitude toward chè's role in Vietnamese culture?", options: ["Appreciative, viewing chè as a meaningful cultural tradition.", "Mildly critical of chè's modern flavor experiments.", "Nostalgic only for northern-style chè recipes specifically.", "Neutral, offering no view on its cultural importance."], answer: 0 }] },
    { title: "Understanding Picky Eating in Young Children", paragraphs: ["Long before most parents encounter a name for it, they encounter the phenomenon itself: a toddler who happily ate a food last month suddenly refuses it outright, sometimes for no reason a parent can identify. What pediatric researchers now call food neophobia — a wariness toward unfamiliar foods that peaks somewhere between the ages of two and six — turns out to be neither rare nor, in most cases, a sign that something has gone developmentally wrong, however alarming it may feel to a parent watching a plate go untouched.", "Several overlapping explanations have been proposed for why this wariness emerges when it does. Some researchers frame it as an evolutionary holdover from a period in human development when a newly mobile toddler, no longer confined to breast milk, benefited from caution toward unfamiliar and potentially toxic plants. Others point instead to heightened sensory sensitivity during this developmental window, noting that many picky eaters report specific textures — sliminess, unexpected crunch, foods that mix multiple textures within a single bite — as more objectionable than the taste itself. Both explanations, researchers increasingly suspect, may be capturing different facets of a single underlying phenomenon rather than competing accounts.", "Parental response to this behavior, several studies suggest, matters considerably more than parents often assume, though not always in the direction intuition would predict. Pressuring a child to finish a disliked food, whether through direct insistence or through less obvious tactics such as offering dessert as a reward for eating vegetables, appears associated in multiple studies with reduced long-term acceptance of that food rather than increased acceptance, possibly because the pressure itself becomes associated with the disliked item and heightens rather than reduces the underlying wariness.", "This dynamic appears especially pronounced among children already identified as having heightened sensory sensitivity, the same subgroup discussed earlier in connection with texture aversion: several researchers have found that pressure-based feeding strategies correlate with particularly poor long-term outcomes specifically within this subgroup, suggesting that a child's underlying sensory profile may determine not just which foods are initially rejected but also how that child responds to parental pressure regarding them. The correlational nature of this research, however, makes it difficult to rule out the possibility that more sensitive children simply provoke more parental pressure in the first place, rather than pressure causing the poorer outcome directly.", "Despite understandable parental anxiety, actual nutritional deficiency among picky eaters appears less common than the anxiety itself would suggest; most picky eaters, when their overall diet is measured carefully rather than assumed from a single unfinished meal, obtain adequate calories and nutrients from a narrower-than-typical but still functional range of accepted foods. Pediatricians generally reserve serious concern for cases involving weight loss, extremely restricted food ranges numbering fewer than a handful of accepted items, or clear signs of physical distress during mealtimes.", "Strategies that researchers now recommend over pressure tend to emphasize repeated, low-stakes exposure: placing a new food on a child's plate without insistence that it be eaten, modeling enjoyment of that food as a parent, and allowing many separate exposures, sometimes a dozen or more, before a child accepts even a small taste. Family meals in which children observe others eating a variety of foods without comment on their own plate appear, in several studies, to modestly increase eventual acceptance.", "Most children, the evidence suggests, gradually outgrow the sharpest edges of food neophobia as they approach school age, though the pace and completeness of this shift varies considerably from child to child. What seems most defensible, given the current state of research, is a posture of patient, low-pressure consistency rather than either anxious intervention or complete indifference."], questions: [{ q: "According to the passage, what did researchers find about children with heightened sensory sensitivity and parental pressure?", options: ["Pressure-based feeding definitely causes worse outcomes in this group.", "This group responds better to pressure than other children.", "This group shows no measurable response to parental feeding style.", "Pressure-based feeding seems linked to worse outcomes in this group."], answer: 3 }, { q: "What is the main idea of the passage?", options: ["Parental pressure has been proven the most effective solution.", "Picky eating is a common phase best met with patience.", "Picky eating is caused only by evolutionary food caution.", "All picky eaters suffer from serious nutritional deficiencies."], answer: 1 }, { q: "The word \"objectionable\" in paragraph 2 is closest in meaning to _______.", options: ["objective", "unpleasant", "unfamiliar", "unbearable"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a recommended feeding strategy?", options: ["Offering monetary rewards for finishing meals", "Repeated, low-stakes exposure to new foods", "Modeling enjoyment of the food as a parent", "Family meals without comment on a child's plate"], answer: 0 }, { q: "What does the passage suggest about nutritional deficiency among picky eaters?", options: ["It appears less common than parental anxiety suggests.", "It is more severe than parents typically realize.", "It only affects children who eat family meals together.", "It is entirely absent among all picky eaters."], answer: 0 }, { q: "The phrase \"This dynamic\" at the start of paragraph 4 refers to _______.", options: ["texture aversion", "sensory sensitivity", "the pressure-reduces-acceptance pattern", "this subgroup"], answer: 2 }, { q: "According to the passage, what sensory quality do many picky eaters find especially objectionable?", options: ["Specific textures, more than taste itself, exclusively.", "Specific textures, more than taste itself.", "Extremely sweet tastes more than any texture.", "Bright colors more than any taste or texture."], answer: 1 }, { q: "The word \"reserve\" in paragraph 5 is closest in meaning to _______.", options: ["limit", "schedule", "reverse", "eliminate"], answer: 0 }, { q: "What can be inferred from the passage about whether parental pressure or a child's sensory sensitivity is the true cause of poor feeding outcomes in sensitive children?", options: ["Pressure has been definitively proven to cause the poor outcomes.", "Poor outcomes always cause parents to reduce feeding pressure.", "The direction of causation remains genuinely unclear.", "Most children outgrow food neophobia by school age."], answer: 2 }, { q: "What is the author's overall attitude toward parental anxiety about picky eating?", options: ["Alarmed, viewing picky eating as a serious medical crisis.", "Dismissive of any parental concern about children's diets.", "Critical only of pediatricians' feeding recommendations.", "Reassuring, suggesting most concern exceeds the actual risk."], answer: 3 }] },
    { title: "Cloud Seeding and the Limits of Weather Modification", paragraphs: ["That humans might induce rainfall on demand has tempted policymakers since at least the mid-twentieth century, when early cloud-seeding experiments — dispersing silver iodide or similar particles into existing clouds to encourage ice crystal formation — generated enough optimistic press coverage that several governments quietly began funding programs before the underlying science had been rigorously validated , a sequencing that continues to complicate the field's credibility even as measurement techniques have substantially improved.", "The basic physical premise is sound enough: introducing particles that serve as nuclei around which ice crystals or water droplets can form may, under the right atmospheric conditions, accelerate precipitation that would otherwise have occurred more slowly or not at all. This premise , however, depends on a cloud already containing sufficient moisture and instability to produce precipitation given the right nucleation trigger — meaning cloud seeding cannot, as popular accounts sometimes imply, generate rain from a clear or moisture-poor sky, however sophisticated the delivery technology becomes.", "Establishing exactly how much additional precipitation a given seeding operation produced has proven considerably more difficult than the underlying chemistry might suggest, precisely because the central counterfactual question — how much rain would have fallen absent intervention — can never be directly observed, only statistically estimated through comparison with similar unseeded storm systems. [1] Randomized field trials, considered the methodological gold standard, remain comparatively rare given the practical and ethical complications of deliberately withholding intervention from a control region during a drought emergency. [2] Where such trials have been conducted, reported precipitation increases have ranged from negligible to perhaps ten or fifteen percent above what similar unseeded clouds produced, a modest effect that nonetheless carries meaningful economic significance across a large agricultural region. [3] This variability itself has become a point of contention among researchers debating how confidently the technique's benefits can be generalized beyond the specific conditions tested. [4]", "Complicating the economic case further is a persistent question that has drawn less public attention than the technique's effectiveness: whether precipitation induced over one region simply relocates moisture that would otherwise have fallen somewhat later over a neighboring region, rather than genuinely increasing the total moisture available within the broader weather system. Some atmospheric scientists argue available modeling suggests this displacement effect, if it exists at all, is likely modest relative to the moisture redistributed naturally by prevailing wind patterns; others maintain the question has not been investigated with anything approaching the rigor its political sensitivity — particularly across international river basins shared by multiple countries — would seem to warrant.", "Government interest in cloud seeding has, notwithstanding these unresolved questions, expanded considerably in recent years, driven substantially by mounting drought pressure in agriculturally significant regions and, in several documented cases, by the perceived need to reduce airborne pollution ahead of major international events through induced rainfall. This expansion has occurred, critics note, at a pace that has generally outstripped the accompanying growth in rigorous, independently verified evaluation of program effectiveness, leaving public investment decisions resting on a thinner evidentiary foundation than the scale of funding might suggest.", "Environmental objections have also surfaced, centering primarily on the long-term ecological effects of repeated silver iodide dispersal into watersheds and agricultural soil, though the available toxicological evidence to date suggests these concentrations, at current operational scales, remain considerably below levels associated with measurable ecological harm — a finding some environmental scientists regard as reassuring and others regard as merely reflecting the field's still-limited long-term monitoring rather than genuine safety.", "Taken together, cloud seeding occupies an uncomfortable middle ground between demonstrated physical plausibility and unresolved practical uncertainty: capable, evidence suggests, of modestly enhancing precipitation under favorable atmospheric conditions, yet still lacking the rigorously quantified track record that would justify either the most enthusiastic government investment or the most dismissive skepticism currently circulating in public discussion."], questions: [{ q: "According to the passage, what unresolved question complicates the economic case for cloud seeding beyond its basic effectiveness?", options: ["Whether government funding for seeding has decreased recently.", "Whether silver iodide is more expensive than alternative chemicals.", "Whether induced rain simply displaces moisture from elsewhere.", "Whether randomized field trials have become too common."], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Cloud seeding has been proven both safe and highly effective.", "Silver iodide has been proven to cause serious ecological harm.", "Cloud seeding can generate rain even from a clear sky.", "Cloud seeding shows modest promise but lacks rigorous evidence."], answer: 3 }, { q: "The word \"validated\" in paragraph 1 is closest in meaning to _______.", options: ["confirmed", "invalidated", "funded", "publicized"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a reason for expanded government interest in cloud seeding?", options: ["Perceived need documented in several countries", "Reducing airborne pollution before major events", "Mounting drought pressure in agricultural regions", "Military weather-control applications during conflict"], answer: 3 }, { q: "According to the passage, what range of precipitation increase have randomized field trials reported?", options: ["Exactly zero percent in all documented trials.", "Consistently above fifty percent in every trial conducted.", "Roughly negligible to about ten or fifteen percent, always confirmed.", "Roughly negligible to about ten or fifteen percent."], answer: 3 }, { q: "The phrase \"This premise\" in paragraph 2 refers to _______.", options: ["silver iodide dispersal only", "the idea that seeding nuclei can accelerate existing precipitation", "measurement technique improvements", "government funding patterns"], answer: 1 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This reliance on indirect comparison is itself a significant source of the field's ongoing measurement difficulty.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }, { q: "The word \"displacement\" in paragraph 4 is closest in meaning to _______.", options: ["enlargement", "relocation", "placement", "destruction"], answer: 1 }, { q: "What can be inferred from the passage about current toxicological findings on silver iodide safety?", options: ["They have been fully replaced by newer, untested chemicals.", "They may reflect limited monitoring rather than confirmed safety.", "They confirm silver iodide causes significant measurable harm now.", "They conclusively prove long-term ecological safety in all conditions."], answer: 1 }, { q: "What is the author's overall attitude toward cloud seeding's current status?", options: ["Balanced, acknowledging plausibility alongside unresolved uncertainty.", "Dismissive, viewing the entire technique as scientifically baseless.", "Enthusiastically supportive of expanded government investment.", "Narrowly focused only on criticizing environmental objections."], answer: 0 }] },
    { title: "Sustainable Building Design: Beyond the Marketing Narrative", paragraphs: ["Not only has sustainable building design moved from an architectural niche to a mainstream expectation among developers and regulators alike, but the term itself has, in the process, absorbed such a broad range of practices — from passive solar orientation to recycled structural materials to elaborate certification schemes — that determining what genuinely reduces a building's environmental footprint, as opposed to what merely signals environmental concern to prospective tenants, has become a substantive research question in its own right rather than a settled matter of professional consensus.", "Certification systems, of which several internationally recognized frameworks now compete for market dominance, award points across categories ranging from energy efficiency to water conservation to indoor air quality, aggregating them into a single rating that developers can market prominently. Whether these aggregate ratings reliably predict actual operational performance once a building is occupied, however, remains considerably more contested than the certificates' prominent display on building facades would suggest; several post-occupancy studies have found that certified buildings sometimes perform little better, and occasionally worse, than comparable uncertified structures, a discrepancy some researchers attribute to a persistent gap between design-stage modeling assumptions and how occupants actually operate a building's systems day to day.", "This design-versus-operation gap, researchers increasingly argue, deserves considerably more attention than it has historically received, since even a building engineered with genuinely sophisticated passive cooling, natural lighting, and high-efficiency mechanical systems can underperform substantially if occupants override automated systems, block designed ventilation pathways with furniture, or operate the building in ways the original energy model never anticipated. [1] Some architects have responded by designing systems deliberately resistant to occupant override, though critics counter that removing occupant control entirely tends to generate its own dissatisfaction and, in some documented cases, prompts occupants to disable systems altogether rather than adapt to them. [2] Others argue the more durable solution lies not in resistant design but in better occupant education and feedback, giving building users real-time information about the energy consequences of their choices. [3] Which approach ultimately proves more effective at closing the performance gap remains, at this stage, an open empirical question rather than a matter of settled professional opinion. [4]", "This gap between intended and realized performance compounds a separate, less visible concern: the carbon emitted during construction itself, sometimes termed embodied carbon, which some researchers argue has received disproportionately less regulatory attention than operational energy use, despite representing, for certain building types, a comparable or even larger share of a structure's total lifetime carbon footprint. Materials such as concrete and steel, indispensable to most large-scale construction, carry substantial embodied carbon costs from their manufacturing processes alone, costs that a building's subsequent decades of efficient operation cannot fully offset within any timeframe relevant to near-term climate targets.", "Retrofitting existing buildings, rather than constructing new ones, has consequently gained traction among some researchers as a comparatively underappreciated strategy, since it avoids much of the embodied-carbon cost associated with new construction while still capturing meaningful operational efficiency gains, though retrofitting older structures presents its own technical constraints — outdated structural systems, historical preservation requirements, asbestos or other hazardous materials — that can make comprehensive upgrades considerably more expensive than a straightforward reading of the carbon savings might suggest.", "Economically, the persistent claim that sustainable buildings command a meaningful rent or resale premium finds mixed support across the available research: premiums appear most consistently documented in prime commercial markets with sophisticated corporate tenants explicitly prioritizing sustainability credentials, while evidence for a comparable premium in residential markets or smaller regional commercial markets remains considerably thinner and, in several studies, statistically indistinguishable from no premium at all.", "Taken together, the evidence suggests sustainable building design delivers genuine environmental benefit under the right conditions, yet considerably less uniformly, and considerably less automatically from certification alone, than the marketing surrounding the field frequently implies — a conclusion that argues less against the underlying goal than for considerably more rigorous, occupancy-informed evaluation of whether specific design choices actually achieve it."], questions: [{ q: "According to the passage, why might certified buildings sometimes underperform despite sophisticated design?", options: ["Embodied carbon always exceeds operational carbon in every case.", "Occupants may override systems in ways the design never anticipated.", "Retrofitted buildings always underperform new construction significantly.", "Certification schemes have been proven entirely fraudulent."], answer: 1 }, { q: "What is the main idea of the passage?", options: ["Certification ratings always accurately predict building performance.", "Embodied carbon has no meaningful impact on total emissions.", "Residential and commercial sustainability premiums are identical everywhere.", "Sustainable design helps, but less uniformly than marketing suggests."], answer: 3 }, { q: "The word \"aggregating\" in paragraph 2 is closest in meaning to _______.", options: ["separating", "aggravating", "combining", "publicizing"], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a technical constraint on retrofitting older buildings?", options: ["Historical preservation requirements limiting changes", "Outdated structural systems requiring upgrades", "Presence of asbestos or hazardous materials", "Higher property insurance premiums on older buildings"], answer: 3 }, { q: "According to the passage, where do sustainability rent or resale premiums appear most consistently documented?", options: ["In prime commercial markets, proven true without exception.", "Only in smaller regional residential markets specifically.", "Equally across residential and commercial markets everywhere.", "In prime commercial markets with sustainability-focused tenants."], answer: 3 }, { q: "The phrase \"This gap\" at the start of paragraph 4 refers to _______.", options: ["certification point categories", "embodied carbon in concrete and steel", "occupant education programs", "the difference between intended and realized building performance"], answer: 3 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'A well-modeled ventilation system, for example, may be rendered useless simply by furniture blocking its intended airflow.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }, { q: "The word \"embodied\" in paragraph 4 is closest in meaning to _______.", options: ["incorporated", "operational", "imagined", "embellished"], answer: 0 }, { q: "What can be inferred from the passage about sustainability premiums in residential real estate markets?", options: ["They have been definitively proven nonexistent everywhere.", "Embodied carbon costs are always fully offset by them.", "Evidence for them is considerably weaker than in prime commercial markets.", "They exceed commercial market premiums in every study."], answer: 2 }, { q: "How does the author's argument develop across the passage?", options: ["It focuses solely on praising embodied-carbon reduction strategies.", "It moves from questioning marketing claims toward calling for rigorous evaluation.", "It moves from technical detail toward dismissing sustainability goals entirely.", "It argues consistently that certification schemes are entirely fraudulent."], answer: 1 }] },
  ] },
];
